BEGIN;

CREATE TYPE "AnnouncementCategory" AS ENUM (
  'events', 'recruitment', 'workshops', 'results', 'community'
);

CREATE TABLE "announcement" (
  "announcement_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "slug" VARCHAR(255) NOT NULL UNIQUE,
  "title" VARCHAR(200) NOT NULL,
  "excerpt" VARCHAR(500) NOT NULL,
  "category" "AnnouncementCategory" NOT NULL,
  "body" TEXT,
  "action_label" VARCHAR(80),
  "action_href" VARCHAR(2048),
  "pinned" BOOLEAN NOT NULL DEFAULT false,
  "published_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "published_by_member_id" INTEGER NOT NULL,
  "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "announcement_publisher_fkey"
    FOREIGN KEY ("published_by_member_id") REFERENCES "member"("member_id")
    ON DELETE RESTRICT ON UPDATE NO ACTION,
  CONSTRAINT "announcement_action_pair_check"
    CHECK (("action_label" IS NULL) = ("action_href" IS NULL))
);

CREATE INDEX "announcement_pinned_published_at_idx"
  ON "announcement" ("pinned", "published_at" DESC);

-- Announcement management is restricted to the two club leadership roles.
INSERT INTO "role_permission" ("role_code", "code")
SELECT roles."role_code", 'announcements.manage'
FROM "role" roles
WHERE roles."role_code" IN ('GROUP_LEADER', 'GROUP_CO_LEADER')
  AND NOT EXISTS (
    SELECT 1 FROM "role_permission" existing
    WHERE existing."role_code" = roles."role_code"
      AND existing."code" = 'announcements.manage'
  );

COMMIT;
